<script setup lang="ts">
const route=useRoute(),token=computed(()=>typeof route.query.token==='string'?route.query.token:'')
const firstName=ref(''),lastName=ref(''),password=ref(''),busy=ref(false),error=ref(''),done=ref(false)
async function submit(){busy.value=true;error.value='';try{await $fetch('/api/account/activate',{method:'POST',body:{kind:'staff',token:token.value,password:password.value,firstName:firstName.value,lastName:lastName.value}});done.value=true}catch(e:any){error.value=e?.data?.message||e?.message||'Registration failed'}finally{busy.value=false}}
</script>
<template><div class="grid min-h-screen place-items-center bg-slate-50 p-4"><form class="w-full max-w-lg space-y-4 rounded-2xl bg-white p-8 shadow" @submit.prevent="submit"><h1 class="text-2xl font-bold">Create staff account</h1><p>Use the email address that received your invitation. A password of at least 12 characters is required.</p><template v-if="!done"><label class="block">First name<input v-model="firstName" required maxlength="100" class="mt-1 w-full rounded-lg border p-3"/></label><label class="block">Last name<input v-model="lastName" required maxlength="100" class="mt-1 w-full rounded-lg border p-3"/></label><label class="block">Password<input v-model="password" required minlength="12" maxlength="128" type="password" autocomplete="new-password" class="mt-1 w-full rounded-lg border p-3"/></label><p v-if="error" role="alert" class="text-red-700">{{error}}</p><button :disabled="busy" class="rounded-lg bg-blue-600 p-3 text-white">{{busy?'Creating…':'Create account'}}</button></template><p v-else class="text-green-700">Account created. <NuxtLink class="underline" :to="'/login?redirect='+encodeURIComponent('/invitations/accept?token='+token)">Sign in to accept your invitation</NuxtLink></p></form></div></template>